refentry.refsect1:
&reftitle.description;
public SoapClient::__construct stringnullwsdl arrayoptions[]
Метод инициализирует объект SoapClient для подключения к службе SOAP.

&reftitle.errors;
Метод SoapClient::__construct генерирует ошибку уровня E_ERROR, если при работе без WSDL-файла не указали настройки location и uri.
Метод выбрасывает исключение SoapFault, если URI из параметра wsdl невозможно загрузить.

  &reftitle.examples;



    Пример инициализации клиента методом SoapClient::__construct


<?php

$client = new SoapClient("some.wsdl");

$client = new SoapClient("some.wsdl", array('soap_version' => SOAP_1_2));

$client = new SoapClient("some.wsdl", array(
    'login'    => "some_name",
    'password' => "some_password"
));

$client = new SoapClient("some.wsdl", array(
    'proxy_host' => "localhost",
    'proxy_port' => 8080
));

$client = new SoapClient("some.wsdl", array(
    'proxy_host'     => "localhost",
    'proxy_port'     => 8080,
    'proxy_login'    => "some_name",
    'proxy_password' => "some_password"
));

$client = new SoapClient("some.wsdl", array('local_cert' => "cert_key.pem"));

$client = new SoapClient(null, array(
    'location' => "http://localhost/soap.php",
    'uri'      => "http://test-uri/"
));

$client = new SoapClient(null, array(
    'location' => "http://localhost/soap.php",
    'uri'      => "http://test-uri/",
    'style'    => SOAP_DOCUMENT,
    'use'      => SOAP_LITERAL
));

$client = new SoapClient(
    "some.wsdl",
    array('compression' => SOAP_COMPRESSION_ACCEPT | SOAP_COMPRESSION_GZIP | 9)
);

$client = new SoapClient("some.wsdl", array('encoding' => 'ISO-8859-1'));

class MyBook
{
    public $title;
    public $author;
}

$client = new SoapClient("books.wsdl", array('classmap' => array('book' => "MyBook")));

$typemap = array(
    array(
        "type_ns"  => "http://schemas.example.com",
        "type_name" => "book",
        "from_xml"  => "unserialize_book",
        "to_xml"    => "serialize_book"
    )
);
$client = new SoapClient("books.wsdl", array('typemap' => $typemap));









    Пример преобразования одиночного элемента в массив при установке флага SOAP_SINGLE_ELEMENT_ARRAYS


<?php

/* Пример строится на основе доступной в виде файла WSDL-спецификации и следующего ответа:
<?xml version="1.0" encoding="UTF-8"?>
<SOAP-ENV:Envelope xmlns:SOAP-ENV="http://schemas.xmlsoap.org/soap/envelope/" xmlns="urn:example">
    <SOAP-ENV:Body>
        <response>
            <collection>
                <item>Single</item>
            </collection>
            <collection>
                <item>First</item>
                <item>Second</item>
            </collection>
        </response>
    </SOAP-ENV:Body>
</SOAP-ENV:Envelope>
*/

echo "По умолчанию:\n";

$client = new TestSoapClient(__DIR__ . '/temp.wsdl');
$response = $client->exampleRequest();
var_dump($response->collection[0]->item);
var_dump($response->collection[1]->item);

echo "\nС флагом SOAP_SINGLE_ELEMENT_ARRAYS:\n";

$client = new TestSoapClient(__DIR__ . '/temp.wsdl', ['features' => SOAP_SINGLE_ELEMENT_ARRAYS]);
$response = $client->exampleRequest();
var_dump($response->collection[0]->item);
var_dump($response->collection[1]->item);




    &example.outputs;



По умолчанию:
string(6) "Single"
array(2) {
  [0] =>
  string(5) "First"
  [1] =>
  string(6) "Second"
}

С флагом SOAP_SINGLE_ELEMENT_ARRAYS:
array(1) {
  [0] =>
  string(6) "Single"
}
array(2) {
  [0] =>
  string(5) "First"
  [1] =>
  string(6) "Second"
}
